SELECT tranyear as yearcode, -1*SUM(CASE WHEN tranmnth = 1 THEN discountedlinetotal ELSE 0 END) AS sales1, -1*SUM(CASE WHEN tranmnth = 1 THEN costtotal ELSE 0 END) AS cost1, -1*SUM(CASE WHEN tranmnth = 1 THEN qty ELSE 0 END) AS units1, -1*SUM(CASE WHEN tranmnth = 2 THEN discountedlinetotal ELSE 0 END) AS sales2, -1*SUM(CASE WHEN tranmnth = 2 THEN costtotal ELSE 0 END) AS cost2, -1*SUM(CASE WHEN tranmnth = 2 THEN qty ELSE 0 END) AS units2, -1*SUM(CASE WHEN tranmnth = 3 THEN discountedlinetotal ELSE 0 END) AS sales3, -1*SUM(CASE WHEN tranmnth = 3 THEN costtotal ELSE 0 END) AS cost3, -1*SUM(CASE WHEN tranmnth = 3 THEN qty ELSE 0 END) AS units3, -1*SUM(CASE WHEN tranmnth = 4 THEN discountedlinetotal ELSE 0 END) AS sales4, -1*SUM(CASE WHEN tranmnth = 4 THEN costtotal ELSE 0 END) AS cost4, -1*SUM(CASE WHEN tranmnth = 4 THEN qty ELSE 0 END) AS units4, -1*SUM(CASE WHEN tranmnth = 5 THEN discountedlinetotal ELSE 0 END) AS sales5, -1*SUM(CASE WHEN tranmnth = 5 THEN costtotal ELSE 0 END) AS cost5, -1*SUM(CASE WHEN tranmnth = 5 THEN qty ELSE 0 END) AS units5, -1*SUM(CASE WHEN tranmnth = 6 THEN discountedlinetotal ELSE 0 END) AS sales6, -1*SUM(CASE WHEN tranmnth = 6 THEN costtotal ELSE 0 END) AS cost6, -1*SUM(CASE WHEN tranmnth = 6 THEN qty ELSE 0 END) AS units6, -1*SUM(CASE WHEN tranmnth = 7 THEN discountedlinetotal ELSE 0 END) AS sales7, -1*SUM(CASE WHEN tranmnth = 7 THEN costtotal ELSE 0 END) AS cost7, -1*SUM(CASE WHEN tranmnth = 7 THEN qty ELSE 0 END) AS units7, -1*SUM(CASE WHEN tranmnth = 8 THEN discountedlinetotal ELSE 0 END) AS sales8, -1*SUM(CASE WHEN tranmnth = 8 THEN costtotal ELSE 0 END) AS cost8, -1*SUM(CASE WHEN tranmnth = 8 THEN qty ELSE 0 END) AS units8, -1*SUM(CASE WHEN tranmnth = 9 THEN discountedlinetotal ELSE 0 END) AS sales9, -1*SUM(CASE WHEN tranmnth = 9 THEN costtotal ELSE 0 END) AS cost9, -1*SUM(CASE WHEN tranmnth = 9 THEN qty ELSE 0 END) AS units9, -1*SUM(CASE WHEN tranmnth = 10 THEN discountedlinetotal ELSE 0 END) AS sales10, -1*SUM(CASE WHEN tranmnth = 10 THEN costtotal ELSE 0 END) AS cost10, -1*SUM(CASE WHEN tranmnth = 10 THEN qty ELSE 0 END) AS units10, -1*SUM(CASE WHEN tranmnth = 11 THEN discountedlinetotal ELSE 0 END) AS sales11, -1*SUM(CASE WHEN tranmnth = 11 THEN costtotal ELSE 0 END) AS cost11, -1*SUM(CASE WHEN tranmnth = 11 THEN qty ELSE 0 END) AS units11, -1*SUM(CASE WHEN tranmnth = 12 THEN discountedlinetotal ELSE 0 END) AS sales12, -1*SUM(CASE WHEN tranmnth = 12 THEN costtotal ELSE 0 END) AS cost12, -1*SUM(CASE WHEN tranmnth = 12 THEN qty ELSE 0 END) AS units12 FROM stocktrans WHERE trandate >= '2024-01-01' and tranyear > '2023' and categoryid in (select categoryid from stockcategory where stockcategory.supercategoryid = 1) and loccode in (select loccode from locationusers where userid ='JACK' and canview = 1) group by tranyear order by tranyear asc 
